import React from 'react';
import { render } from '@testing-library/react';
import { MemoryRouter } from 'react-router-dom';
import { ThemeProvider } from 'styled-components';

import { theme } from 'theme';
import 'i18n';
import App from './App';

const renderAt = (path: string) => render(
  <ThemeProvider theme={theme}>
    <MemoryRouter initialEntries={[path]}>
      <App />
    </MemoryRouter>
  </ThemeProvider>,
);

test('renders the app shell on the welcome route', () => {
  const { container, queryByText } = renderAt('/dubai-app/welcome');
  expect(container.firstChild).not.toBeNull();
  expect(queryByText('404 Page')).toBeNull();
});

test('shows the 404 page for an unknown route', () => {
  const { getByText } = renderAt('/no-such-page');
  expect(getByText('404 Page')).toBeInTheDocument();
});
